"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["94157"],{35396(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.precedencia_fase.ciclo_detectado","status":422,"titulo":"A aresta fecharia um ciclo no grafo de preced\xeancias"},"descricao":{"codigo":"uniplus.configuracao.precedencia_fase.ciclo_detectado","requisitos":[],"oQueAconteceu":["O cadastro de uma preced\xeancia (`POST /api/configuracao/admin/precedencias-fase`) ligaria uma fase antecessora a uma sucessora de modo que, junto com as preced\xeancias que j\xe1 existem, a sucessora passaria a preceder a antecessora, direta ou por um caminho de outras fases. Seria um ciclo: cada fase do caminho teria de vir antes das outras, e nenhum cronograma que as contivesse poderia ser cumprido. O caso mais simples \xe9 cadastrar o par inverso de um par j\xe1 existente.","Esta \xe9 a \xfaltima confer\xeancia do cadastro, depois da dos c\xf3digos, da de fase sobre si mesma e da de par duplicado. A resposta traz o c\xf3digo de erro e a mensagem, sem a lista `errors`. Nada \xe9 gravado."],"comoResolver":["Confira as preced\xeancias existentes (`GET /api/configuracao/precedencias-fase`) e verifique se a ordem entre as duas fases est\xe1 invertida. Se a preced\xeancia existente que fecha o caminho de volta deve ser desfeita, remova-a (`DELETE /api/configuracao/admin/precedencias-fase/{id}`) antes de cadastrar a nova. Antecessora e sucessora de uma preced\xeancia existente n\xe3o s\xe3o edit\xe1veis."],"ondeAparece":["Cadastro de uma preced\xeancia entre fases"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Precedencia fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);